// Fontes e senhas vem da Data Table 'Faturas - Fontes e Senhas'.
// Para adicionar um banco novo, acrescente uma linha na tabela — nao mexa neste codigo.
const rows = $input.all();
const emails = $('Buscar Emails Faturas').all();

function norm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function getHeader(headers, name) {
  if (!Array.isArray(headers)) return '';
  const h = headers.find(x => x && x.name && x.name.toLowerCase() === name);
  return h ? (h.value || '') : '';
}

const SOURCES = [];
for (const r of rows) {
  const j = r.json || {};
  if (j.enabled === false) continue;
  if (!j.sender_match) continue;
  SOURCES.push({
    issuer: j.issuer || 'desconhecido',
    senderMatch: norm(j.sender_match),
    subjectMatch: norm(j.subject_match),
    password: j.password == null ? '' : String(j.password)
  });
}

if (!SOURCES.length) {
  console.warn('ATENCAO: nenhuma fonte activa na Data Table — nada sera processado.');
}

function resolveSource(from, subject) {
  const f = norm(from);
  const s = norm(subject);
  for (const src of SOURCES) {
    if (f.indexOf(src.senderMatch) === -1) continue;
    if (src.subjectMatch && s.indexOf(src.subjectMatch) === -1) continue;
    return src;
  }
  return null;
}

const results = [];
const seen = new Set();
let ignorados = 0;

for (const item of emails) {
  if (!item.binary) continue;
  const j = item.json || {};
  const msgId = j.id || j.threadId || Math.random().toString(36);
  const headers = (j.payload && j.payload.headers) || [];

  let from = getHeader(headers, 'from');
  if (!from && j.From) from = j.From;
  if (!from && j.from && j.from.value && j.from.value[0]) from = j.from.value[0].address || '';
  if (!from && typeof j.from === 'string') from = j.from;

  let subject = getHeader(headers, 'subject');
  if (!subject && j.Subject) subject = j.Subject;
  if (!subject && j.subject) subject = j.subject;

  const src = resolveSource(from, subject);
  if (!src) {
    ignorados++;
    console.log('ignorado (sem fonte correspondente): from=' + from + ' subject=' + subject);
    continue;
  }

  const rawDate = j.internalDate || j.date || null;
  let emailDate = new Date().toISOString().slice(0, 10);
  if (rawDate) {
    const d = new Date(Number(rawDate) > 0 ? Number(rawDate) : rawDate);
    if (!isNaN(d.getTime())) emailDate = d.toISOString().slice(0, 10);
  }

  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];
    const fileName = (bin.fileName || '').trim();
    if (!fileName) continue;
    const isPdf = (bin.mimeType || '').toLowerCase().includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const dedupKey = msgId + '::' + fileName;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    results.push({
      json: {
        msgId, emailDate, fileName, from, subject,
        issuer: src.issuer,
        password: src.password
      },
      binary: { data: bin }
    });
  }
}

console.log('faturas: ' + results.length + ' pdf(s) aceites, ' + ignorados + ' email(s) ignorado(s)');
return results;

const src = $('Config e Filtrar PDFs').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const meta = src[i] ? src[i].json : {};
  const pages = (j.pages || []).map(p => 'data:image/png;base64,' + ((p && p.image && p.image.data) || ''));
  out.push({ json: Object.assign({}, meta, {
    pages: pages,
    pageCount: pages.length,
    convertError: pages.length ? undefined : 'sem paginas'
  }) });
}
return out;

